const y=[{id:"T01",title:"Dai, Milkman & Riis · 2014 · The fresh-start effect",url:"https://faculty.wharton.upenn.edu/wp-content/uploads/2014/06/Dai_Fresh_Start_2014_Mgmt_Sci.pdf",type:"research",finding:"Üç arşiv veri kümesinde, takvimde yeni dönemleri işaretleyen günlerin çevresinde hedefe başlama arttı. Ölçüler diyet aramaları, üniversite spor salonu ziyaretleri ve taahhüt sözleşmeleriydi.",limitation:"Gözlemsel başlama ölçüleri neden-sonuç, sürdürülen değişim veya rastgele bir güne başlangıç demenin etkisini göstermez."},{id:"T02",title:"Dai, Milkman & Riis · 2015 · Temporal landmarks and goal initiation",url:"https://anderson-review.ucla.edu/wp-content/uploads/2021/03/Dai-Milkman-Riis_2015_TemporalLandmarks_APS_0956797615605818.pdf",type:"research",finding:"İnternetten katılan 165 yetişkinin %25,61’i, 20 Mart baharın başlangıcı olarak sunulunca o güne hatırlatma seçti. Tarih üçüncü perşembe olarak sunulunca oran %7,23’tü.",limitation:"Karşılaştırma, gerçek davranışı veya kalıcı değişimi değil hatırlatma seçimini ölçtü. Kendi başlangıç gününü ilan etmek ODA uyarlamasıdır."},{id:"T03",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"8.461 kişinin katıldığı 94 bağımsız testte, belirli “şu olursa bunu yaparım” planları hedefe ulaşmayı ortalama olarak artırdı: d = 0,65, %95 güven aralığı [0,60; 0,70].",limitation:"Farklı ortamlar ve eski yöntemler genellemeyi sınırlar. Etki başarıda %65 artış değildir. ODA’nın bu kısa planı sınanmadı."},{id:"T04",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8149892/",type:"research",finding:"15.907 kişinin katıldığı, 24 etki içeren 21 makalenin meta-analizinde hedefe ulaşmada küçük bir ortalama yarar bulundu: g = 0,336, %95 güven aralığı [0,229; 0,443].",limitation:"Sonuçlar farklıydı, yayın yanlılığı olasıydı. Katılımcı toplamında iki büyük çevrim içi örneklem baskın. Hayal etmek sonuçları çekmez. ODA alıştırması sınanmadı."},{id:"T05",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"19.951 kişinin katıldığı 138 rastgele kontrollü çalışmada ilerlemeyi izleme uygulamaları hedefe ulaşmayı ortalama olarak artırdı: d = 0,40, %95 güven aralığı [0,32; 0,48].",limitation:"Hedefler ve yöntemler farklıydı. Ek analizlerde fiziksel kayıt ve bildirim daha büyük etkilerle ilişkiliydi. Herkese açık paylaşım gerekmez. ODA’nın bu kayıt biçimi sınanmadı."},{id:"T06",title:"Lally et al. · 2010 · Modeling habit formation",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"84 günlük gözlemsel çalışma 96 gönüllüyü izledi. Verilere iyi uyan 39 eğride, otomatikliğin her kişideki üst sınırının %95’ine ulaşma süresi 18–254 gün olarak tahmin edildi. Ortanca 66 gündü.",limitation:"Bunlar model tahminleriydi, gözlenmiş bitiş tarihleri değil. Kişinin bildirdiği gündelik sağlık davranışları, herkese uyan süreyi veya iki fırsat kaçırma eşiğini göstermez."},{id:"T07",title:"Singh et al. · 2024 · Time to form a habit",url:"https://doi.org/10.3390/healthcare12232488",type:"research",finding:"2.601 kişinin katıldığı 20 sağlık davranışı çalışmasının derlemesinde, oluşma süresi tahminleri çok farklıydı. Yalnızca dört çalışma süre tahmini verdi. Bireysel tahminler 4 ile 335 gün arasındaydı.",limitation:"On bir çalışmada yanlılık riski yüksekti. Süre tanımları farklıydı. Öncesi ve sonrası arasındaki alışkanlık gücü farkı, kontrollü tedavi etkisi veya kişisel son tarih değildir."},{id:"T08",title:"Wood & Rünger · 2016 · Psychology of habit",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",type:"research",finding:"Derleme, benzer ortamlarda tekrarladığımız davranışları zamanla o ortamdaki işaretlerle yapmaya başlayabildiğimizi anlatır. Bilinçli hedefler ile alışkanlıklar birlikte işleyebilir.",limitation:"Farklı araştırmaları birleştiren anlatı derlemesidir. Yeni bir deney sunmaz, tek bir ortak etki büyüklüğü hesaplamaz. Nesnelerin yerinin isteği gereksiz kıldığını veya her karmaşık hedefin otomatikleştiğini göstermez."},{id:"T09",title:"Bandura · 1977 · Self-efficacy theory",url:"https://dradamvolungis.com/wp-content/uploads/2011/06/self-efficacy-unifying-theory-of-behavioral-change-bandura-1977.pdf",type:"research",finding:"Bandura’nın kuramı; kendi başardıklarını, başkalarını izlemeyi, cesaretlendirilmeyi ve bedensel durumları belirli bir davranışı yapma beklentisinin kaynakları olarak tanımlar. Kişinin kendi başardığı işlere özellikle önem verir.",limitation:"Önceki araştırmaları birleştiren kuramdır, yeni deney değildir. Her küçük işin özgüveni artırdığını veya genel yeteneği kanıtladığını göstermez."},{id:"T11",title:"Scullin et al. · 2018 · Bedtime task-list writing",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC5758411/",type:"research",finding:"Bir laboratuvar gecesinde, 18–30 yaşındaki 57 sağlıklı yetişkin beş dakika kâğıda gelecek işleri veya tamamlanan işleri yazdı. Ortalama uykuya dalma süresi 15,82 ve 25,09 dakikaydı.",limitation:"Karşılaştırma başka bir yazma işiydi. Toplam uykuda istatistiksel olarak anlamlı artış veya uzun süreli uykusuzluk yararı gösterilmedi. Sözlü telkinler ve ODA’nın kısa değerlendirmesi sınanmadı."},{id:"T12",title:"Wohl, Pychyl & Bennett · 2010 · Self-forgiveness and exam procrastination",url:"https://doi.org/10.1016/j.paid.2010.01.029",type:"research",finding:"119 birinci sınıf öğrencisinde, bir ara sınav öncesindeki erteleme için daha fazla kendini affetmek, sonraki sınav öncesinde daha az ertelemeyle ilişkiliydi.",limitation:"Tek bir dersteki gözlemsel ölçümler neden-sonuç göstermez. Özet bir etki katsayısını veya hazır cümlenin yararını doğrulamaz."},{id:"T15",title:"Oettingen et al. · 2015 · Mental contrasting and time management",url:"https://www.socmot.uni-konstanz.de/sites/default/files/Oettingen_et_al-2015-European_Journal_of_Social_Psychology_0.pdf",type:"research",finding:"İlk çalışmada 84 Alman lisans öğrencisi rastgele gruplara ayrıldı. Birleşik alıştırma grubu iki kontrol grubundan daha çok saat planladı. Önceden planlanan karşılaştırma istatistiksel olarak anlamlıydı. Genel koşul testinde p = 0,057 bulundu.",limitation:"Planlanan saatler niyet ölçüsüydü. Çalışılan saat veya biten proje değildi. Çalışma, ODA’nın kısa adımını ve ertesi gün değerlendirmesini doğrulamaz."},{id:"T17",title:"James Clear · The two-minute rule",url:"https://jamesclear.com/how-to-stop-procrastinating",type:"technique",finding:"Clear, yeni bir davranışa başlarken yapılacak kısa bir iş seçmeyi önerir. Bu, başlaması kolay bir adım seçmek için uygulamaya dönük bir öneridir.",limitation:"Tam iki dakikanın en iyi süre olduğu kontrollü araştırmayla gösterilmedi. Hazırlık ile hedeflenen davranışın işe yarayan bir parçasını tamamlamak aynı şey değildir."},{id:"bandura-self-efficacy",title:"Bandura · 1977 · Self-efficacy theory",url:"https://dradamvolungis.com/wp-content/uploads/2011/06/self-efficacy-unifying-theory-of-behavioral-change-bandura-1977.pdf",type:"research",finding:"Bandura’nın kuramı; kendi başardıklarını, başkalarını izlemeyi, cesaretlendirilmeyi ve bedensel durumları belirli bir davranışı yapma beklentisinin kaynakları olarak tanımlar. Kişinin kendi başardığı işlere özellikle önem verir.",limitation:"Önceki araştırmaları birleştiren kuramdır, yeni deney değildir. Her küçük işin özgüveni artırdığını veya genel yeteneği kanıtladığını göstermez."},{id:"habits",title:"Lally et al. · 2010 · Modeling habit formation",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"84 günlük gözlemsel çalışma 96 gönüllüyü izledi. Verilere iyi uyan 39 eğride, otomatikliğin her kişideki üst sınırının %95’ine ulaşma süresi 18–254 gün olarak tahmin edildi. Ortanca 66 gündü.",limitation:"Bunlar model tahminleriydi, gözlenmiş bitiş tarihleri değil. Kişinin bildirdiği gündelik sağlık davranışları, herkese uyan süreyi veya iki fırsat kaçırma eşiğini göstermez."},{id:"oettingen-woop-method",title:"Gabriele Oettingen · WOOP",url:"https://woopmylife.org/en/home",type:"technique",finding:"WOOP; bir isteği, arzulanan sonucu, iç engeli ve “şu olursa bunu yaparım” planını birleştirir. İlgili araştırmalar planlamayı ortalama olarak destekler, sonuçlar değişir.",limitation:"Geliştiricinin sitesi bağımsız değerlendirme değildir. MCII bulguları yöntemin her biçimini doğrulamaz. Dış koşulları düşünce biçiminin kusuru hâline getirmez."}],d=[{schemaVersion:2,revision:2,id:"turning-day-1",courseId:"turning-day",locale:"tr",title:"Pazartesiyi bekleme. Bugün küçük bir başlangıç yap",goal:"Seçtiğin yolda işe yarayan küçük bir adım at. Ardından bir sonraki deneme zamanını belirle.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Hangi isteğini hep gelecek pazartesiye bırakıyorsun? Bugün ona yer aç.",reason:{id:"turning-day-1-reason",label:"İki dakikanı neye ayırmak istersin, ne biraz daha bekleyebilir?",kind:"text",maxLength:160,optional:!0,suggestions:["Yaratıcılığıma zaman ayırmak","Hafta geçmeden küçük bir deneme yapmak","Önemsediğime zaman ayırmak"]},why:{id:"turning-day-1-why",label:"İki dakikanı neye ayırmak istersin, ne biraz daha bekleyebilir?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bir tarihe nasıl baktığın, başlama kararını etkileyebilir. Bu, devam edeceğini göstermez. Bir deneyde aynı mart günü “baharın başlangıcı” diye sunulduğunda daha çok kişi o gün için hatırlatma seçti. Araştırma, bu hatırlatmalardan sonra kimlerin gerçekten bir adım attığını göstermedi. Hatırlatma seçmek ile işe başlamak ayrı şeyler.","Şimdi bu fırsatı kendi seçtiğin yolda küçük bir şey yapmak için kullan. Bir nesne çiz, işe yarayan bir cümle yaz veya ihtiyacın olan paragrafı oku. Tarih belirlemek hazırlıktır. Seçtiğin işi yap, ne yaptığını kaydet ve sıradaki başlangıç anını seç. Kurs boyunca aynı denemeyi sürdüreceğiz."],example:{title:"Derya ilk çizimini yapıyor",text:"Derya çizim yapmak için hep pazartesiyi bekliyor. Çarşamba günü mutfak masasında çayını bitirince iki dakika fincanını çiziyor. Kulp biraz yamuk oluyor. Bir çizim yaptığını kaydedip sıradaki deneme için yarınki çayını seçiyor. Çarşambaya “başlangıç” demek seçim yapmasını kolaylaştırdı. Çizim becerisini artırmadı. Elinde kusursuz bir sonuç yok, yaptığı küçük çizim var."}},move:{invitation:"Çizmek, yazmak veya okumak sana bir şey katacaksa bu örneklerden birini seç.",instructions:["Boş planı doldurmadan önce örneğin istediğin yola uyup uymadığını kontrol et.","Seçtiğin adımı dene, sonra buraya dönüp ne yaptığını kaydet."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Bir sonraki çayımı bitirince","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Daha küçük nesne veya bana uygun araçlar kullan","Yazmak zorsa bir cümleyi sesle yazdır","Bana uygun metni kullan veya sesli oku"],observation:["Tamamladığım küçük çizim","Yazdığım işe yarayan cümle","Okuyup bitirdiğim paragraf"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"Bir sonraki çayımı bitirince",place:"Evde, mutfak masamın başında",fallback:"Daha küçük nesne veya bana uygun araçlar kullan",observation:"Tamamladığım küçük çizim",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"Sonraki öğünümü bitirince",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Yazmak zorsa bir cümleyi sesle yazdır",observation:"Yazdığım işe yarayan cümle",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Bana uygun metni kullan veya sesli oku",observation:"Okuyup bitirdiğim paragraf",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"Bir sonraki çayımı bitirince",placeHint:"Evde, mutfak masamın başında",obstacleHint:"Kullanabildiğim zaman veya araçlar değişiyor",fallbackHint:"Daha küçük nesne veya bana uygun araçlar kullan",observationHint:"Tamamladığım küçük çizim",requiresChoice:!0},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Güvenli bir iş seç. Sağlık, bakım sorumlulukları veya erişim ihtiyaçları önce geliyorsa adımı değiştir ya da ara ver."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Tam olarak ne yaptın, önüne hangi engel çıktı?"},judgment:{primary:{id:"turning-day-1-decision",scenario:"Derya mutfak masasında. İki boş dakikası ve kâğıdı var. Çizim yapmak istiyor ama genellikle başlamak için pazartesiyi bekliyor.",question:"Bu durumda hangi adım ona daha uygun?",options:[{id:"draw-now",text:"Hemen yakındaki fincanı çiz, yaptığın çizimi kaydet ve yarın için uygun bir deneme zamanı seç.",feedback:"Bu adım, elindeki fırsatı gerçekten çizim yapmak için kullanıyor. Çizim kabaca çizilmiş olabilir. Tamamladığın küçük işi kaydet. Sonra aynı denemeyi sürdürmek için bir sonraki başlangıç anını belirle."},{id:"schedule-course",text:"Bu iki dakikayı gelecek hafta başlayabileceğin kapsamlı bir çizim kursunun zamanını ayarlamak için kullan.",feedback:"Bir kurs ileride işe yarayabilir. Ama Derya şu anda bir çizim için yeterli zamana ve malzemeye sahip. Zaman ayarlamak plan yapmak olur. Çizmek ise bugün istediği yönde bir denemedir."},{id:"choose-supplies",text:"Yeni başlayanlara uygun çizim malzemelerini karşılaştır, sonra hangi nesneyi çizmenin daha kolay olacağına karar ver.",feedback:"Malzeme eksikse uygun araç seçmek gerekir. Derya’nın ise kâğıdı ve çizebileceği bir nesne var. Daha fazla seçim yapmak, bu fırsatı çizim denemesi yapmadan tüketir."}],bestOptionId:"draw-now"}},carry:{takeaway:"Küçük bir iş yaptığında, başlangıcının somut bir karşılığı olur.",followUp:{questionId:"turning-day-1-return",question:"Seçtiğin başlangıç anı geldiğinde işe yarayan küçük adımını gerçekten attın mı?",observationPrompt:"Gerçekte ne yaptın ya da ne fark ettin?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"Hatırlatma seçmek, bir işi denemek değildir",paragraphs:["Dai, Milkman ve Riis, 2014’te üç arşiv veri kümesiyle yeni başlangıçları inceledi [T01]. Takvimde yeni bir dönemi işaretleyen bazı günlerin çevresinde diyet aramaları, üniversite spor salonu ziyaretleri ve yeni taahhüt sözleşmeleri arttı. Bunlar birbirinden farklı başlama ölçüleridir. Takvimdeki o günün değişime neden olduğunu veya insanların hedeflerini uzun süre sürdürdüğünü göstermez.","Daha sonraki bir deneyde, internet üzerinden katılan 165 yetişkin hedefleri için hatırlatma tarihleri arasından seçim yaptı [T02]. 20 Mart “baharın başlangıcı” diye sunulunca %25,61’i o tarihte hatırlatma istedi. Aynı tarih “ayın üçüncü perşembesi” diye sunulunca bu oran %7,23 oldu. Burada ölçülen şey hatırlatma seçmekti. Sonrasında kimin gerçekten bir şey yaptığını bu karşılaştırmadan bilmiyoruz.","Bugüne “benim başlangıcım” demek, ODA’nın sunduğu isteğe bağlı bir bakış açısıdır. Rastgele bir güne bu adı vermenin araştırmadaki sonuçları tekrarlayacağını söylemiyoruz. Senin kaydın, bugüne verdiğin addan değil, gerçekten yaptığın işten başlar."]},{heading:"Ne zaman, nerede, ne yapacağını belirle",paragraphs:["“Şu olursa bunu yapacağım” planı, tanıyabileceğin bir durumla önceden seçtiğin bir davranışı birleştirir. Gollwitzer ve Sheeran, 8.461 kişinin katıldığı 94 bağımsız testi bir araya getirdi [T03]. Bu planlar, incelenen ortamlarda hedefe ulaşmayı ortalama olarak artırdı. İşler, katılan kişiler ve araştırma yöntemleri farklıydı. Bu yüzden ortalama sonuç senin sonucunu önceden söylemez. Bu kısa ODA dersi o derlemede sınanmadı.","Bu deneme için istediğin yola katkısı olan küçük bir iş seç. “Mutfak masasında çayımı bitirince bir nesne çizeceğim” cümlesi başlangıç anını, yeri ve işi anlatır. Kâğıdı ortaya koymak hazırlıktır. Nesneyi çizmek çizim denemesidir. İkisi de gerekli olabilir. Kaydına hangisini gerçekten yaptığını yaz.","Seçtiğin yol bakım sorumluluklarını üstlenmek, toparlanmak, yakınlık kurmak veya öğrenmek için olabilir. Bulunduğun yer güvenli bir adıma uygun değilse daha sonra uygun bir zaman seç ya da destek al. Takvimde bir güne yeni bir ad vermek, önündeki gerçek engeli ortadan kaldırmaz."]}],sourceIds:["T01","T02","T03"]}},{schemaVersion:2,revision:2,id:"turning-day-2",courseId:"turning-day",locale:"tr",title:"Planın eve gelince dağılıyor mu? O ana hazırlan",goal:"Sürdürdüğün denemede önüne çıkabilecek tek bir engel için yapabileceğin bir adım seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kâğıt üzerinde iyi görünen planın, günün hangi anında gerçek hayatına uymuyor?",reason:{id:"turning-day-2-reason",label:"Son denemeni ne durdurdu, bunun hangi kısmını değiştirebilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Seçtiğim an geldiğinde hâlâ işteydim","Vardiyadan sonra dinlenmem gerekiyordu","Gereken araca ulaşamadım"]},why:{id:"turning-day-2-why",label:"Son denemeni ne durdurdu, bunun hangi kısmını değiştirebilirsin?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İşe yarayan küçük adımını koru. Önünü ne kesebilir, ona bak. Başa çıkabileceğin bir duygu veya tepki başka, çocuğa bakacak birinin, gerekli malzemenin ya da güvenli bir yerin olmaması başka. Gücünün yetmemesi de gerçek bir engel olabilir. Her engeli kendi içinde çözmen gereken bir sorun sayma. Plan hayatına uymuyorsa onu değiştir. Gerçek koşulları plana kat.","Bir engelle veya fırsatla karşılaştığında ne yapacağını seç: “İşten gelip montumu çıkarınca masada bir nesne çizeceğim.” Araştırmalar, böyle belirli planları ortalama olarak destekliyor. Sonuçlar değişiyor. Planı yazmak hazırlıktır. Seçtiğin işi o anda dene. Sonra bunu yapmanın mümkün olup olmadığını ve yapıp yapmadığını kaydet."],example:{title:"Derya için saat değil, eve dönüş",text:"Derya’nın vardiyaları farklı saatlerde bitiyor. Bu yüzden çizim planındaki 18.00 çoğu gün uymuyor. Başlangıç anını, eve gelip montunu çıkarmak olarak değiştiriyor. Diziyi açmadan önce mutfak masasında anahtarlarını çiziyor. Kabaca da olsa bir çizimi tamamlıyor. Ertesi gün vardiyası geç bitiyor ve bu kez dinlenmeye ihtiyaç duyuyor. O gün de koşullarına bakıyor."}},move:{invitation:"Kaydettiğin işi ve en küçük adımı koru. Gördüğün bir engele veya fırsata göre planını değiştir.",instructions:["Sana uyan başlama anını koru. Karşılaştığın engele göre “Engelle karşılaşınca” alanını değiştir.","Henüz denemediysen aynı iş için sana uygun bir başlangıç anı seç."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["İşten gelip montumu çıkardığım anda","Önceden ayırdığım mola başladığında","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Dinlen; yarın öğleden sonraki molada tekrar dene","Dinlen; yarın işte uygun olan molada dene","Dinlen; yarın yemeğini yedikten sonra okumayı dene"],observation:["Seçtiğim an geldi mi, çizimi yaptım mı?","Seçtiğim an geldi mi, cümleyi yazdım mı?","Seçtiğim an geldi mi, paragrafı okudum mu?"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"İşten gelip montumu çıkardığım anda",place:"Evde, mutfak masamın başında",fallback:"Dinlen; yarın öğleden sonraki molada tekrar dene",observation:"Seçtiğim an geldi mi, çizimi yaptım mı?",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"Önceden ayırdığım mola başladığında",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Dinlen; yarın işte uygun olan molada dene",observation:"Seçtiğim an geldi mi, cümleyi yazdım mı?",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Dinlen; yarın yemeğini yedikten sonra okumayı dene",observation:"Seçtiğim an geldi mi, paragrafı okudum mu?",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"İşten gelip montumu çıkardığım anda",placeHint:"Evde, mutfak masamın başında",obstacleHint:"Vardiya bittikten sonra dinlenip toparlanmaya ihtiyacım var",fallbackHint:"Dinlen; yarın öğleden sonraki molada tekrar dene",observationHint:"Seçtiğim an geldi mi, çizimi yaptım mı?"},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Bitkinken, tehlike varken veya gereken şeylere erişemiyorken kendini zorlama. Dinlenmeyi, desteği ya da başka bir fırsatı seç."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Tam olarak ne yaptın, önüne hangi engel çıktı?"},judgment:{primary:{id:"turning-day-2-workday-cue-decision",scenario:"Derya normal iş günlerinde kısa çizimler yapmak istiyor. Vardiyalar değiştiği için 18.00’de çoğu zaman işte. Montunu evde çıkarıyor. O sırada genellikle iki boş dakikası oluyor.",question:"Her gün yeniden saat ayarlamadan hangi plan iş günlerine uyar?",options:[{id:"days-off-session",text:"Enerjisini korumak için izin günlerinde kısa çizimler yapmayı seçsin. Böylece iş günlerinde daha az çizim fırsatı olacağını kabul etsin.",feedback:"İzin günlerinde denemek dinlenmeyi koruyabilir ve başka bir amaca uyabilir. Derya ise iş günlerinde kısa fırsatlar istiyor. Eve dönüş anı, her vardiyanın bitişini tahmin etmeden böyle bir fırsat sunuyor."},{id:"coat-cue",text:"Montunu çıkardıktan sonra bir nesne çizsin. Çok yorgunsa dinlensin veya başka bir uygun başlangıç anı seçsin.",feedback:"Bu plan tanınabilir bir anı kullanıyor ve dinlenme ihtiyacını koruyor. Derya aynı küçük çizimi deneyebilir. Sabit bir saat veya daha güçlü bir hatırlatma, vardiyalarını değiştiremez."},{id:"shift-calendar-alert",text:"Her gün vardiya takvimini kontrol edip beklenen çıkış saatinden otuz dakika sonrasına bir çizim hatırlatması kursun.",feedback:"Çıkış saatleri tutuyorsa bu plan işe yarayabilir. Değişen vardiyalarda hatırlatmaları ayarlamak ek iş ve belirsizlik getirir. Eve dönüş, uygun yeri zaten işaretliyor. Dinlenme seçeneğini koruyarak o anı dene."}],bestOptionId:"coat-cue"}},carry:{takeaway:"Elindeki koşullara göre plan yap. Sonra seçtiğin işi o durumda dene.",followUp:{questionId:"turning-day-2-return",question:"Seçtiğin başlama anı geldi mi? O anda planladığın işi gerçekten yapabilir miydin?",observationPrompt:"Gerçekte ne yaptın ya da ne fark ettin?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"Her engel senin içinde değildir",paragraphs:["Zihinsel karşılaştırma, istediğin sonucu ona ulaşmanın önündeki engelle birlikte düşünmektir. Buna “şu olursa bunu yaparım” planı eklenince yöntem çoğu zaman MCII diye anılır. Wang ve arkadaşları, 15.907 kişinin katıldığı, 24 bağımsız etki içeren 21 makaleyi inceledi [T04]. Hedefe ulaşmada küçük bir ortalama yarar buldular. Sonuçlar araştırmalar arasında değişiyordu. Yayın yanlılığı olasılığı da vardı.","Bu yaklaşım bazen isteğin kendisini değiştirmek gerektiğini gösterir. Bir sonucu hayal etmenin onu hayatına çekeceğini, her engelin bir duygu olduğunu veya daha çok zorlanmanın her zaman doğru olduğunu göstermez. Planın mümkün olup olmadığını değerlendirirken dış koşulları da hesaba kat. Para, engellilikle ilgili erişim ihtiyaçları, iş yükü ve bakım sorumlulukları “canım istemiyor” diye açıklanamaz.","ODA’nın uyarlaması, seçtiğin yönü koruyup o durum için seçtiğin işi denemeni ister. Bu, işi küçültmek, başka bir an seçmek veya somut bir yardım istemek olabilir. İşe yarayıp yaramadığına karar vermeden önce o işi gerçekten yapıp yapamayacağını kaydet."]},{heading:"Daha çok saat planlamak hâlâ plan yapmaktır",paragraphs:["Zaman yönetimi üzerine bir araştırmada 84 Alman lisans öğrencisi rastgele üç gruba ayrıldı [T15]. Zihinsel karşılaştırmayı planlamayla birleştiren grup, kontrol gruplarından daha çok çalışma saati planladı. Önceden planlanan karşılaştırma istatistiksel olarak anlamlıydı. Koşulların genel testinde ise p = 0,057 bulundu. Ölçülen sonuç takvime ayrılan saatlerdi. Araştırma, öğrencilerin gerçekte kaç saat çalıştığını göstermedi.","Daha geniş bir derlemede, belirli “şu olursa bunu yaparım” planları hedefe ulaşmayı ortalama olarak artırdı [T03]. Bu deneyler tek bir zamanlayıcı süresini veya herkese uyan günlük bir süreyi sınamadı. Burada seçtiğin işi denemek ve ertesi gün ne olduğuna bakmak eğitim için uyarlanmış adımlardır. Özgün araştırma uygulaması değildir.","Denemeye bakarken üç soruyu ayır: Başlama anı geldi mi? Planladığın işi yapabilir miydin? Yaptın mı? Engel hiç çıkmadıysa alternatif planın henüz sınanmadı. İşi yapman mümkün değilse kendini yargılamak yerine koşulları veya planını değiştir."]}],sourceIds:["T03","T04","T15"]}},{schemaVersion:2,revision:2,id:"turning-day-3",courseId:"turning-day",locale:"tr",title:"“Ben hiç sürdüremiyorum.” Kaydın da bunu mu söylüyor?",goal:"Aynı denemede işe yarayan küçük adımını tamamla. Bu denemenin tam olarak neyi gösterdiğini anlat.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Tek bir kötü denemeden, bütün hayatın hakkında bir hüküm mü çıkardın?",reason:{id:"turning-day-3-never-fact-check-reason",label:"Son denemen “hiç yapamıyorum” sözünün hangi kısmını destekliyor, hangi kısmına uymuyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Bir iş yaptım; becerim hâlâ gelişmeli","Başlangıç anı gelmedi; becerimi henüz sınamadım","Henüz kaydettiğim bir deneme yok"]},why:{id:"turning-day-3-why",label:"Bu hafta dürüstçe kaydedeceğin küçük bir deneme neye katkı sağlar?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Belirli bir işi yapabileceğine inanman ile insan olarak değerin ayrı şeyler. Bir kurama göre, bu beklentiyi şekillendiren önemli kaynaklardan biri daha önce başardığın işlerdir. Bu, her küçük adımın özgüvenini artıracağını veya birçok konuda yetenekli olduğunu kanıtlayacağını göstermez. Burada bütün kişiliğine bir not vermiyoruz. Tek bir işe bakıyoruz.","Aynı küçük adımına dön. Yaptığını tam anlat: “Bir nesne çizdim. Dış hatlarını çalışmam gerekiyor.” Kusurlu bir deneme, seçtiğin en küçük adımı karşılayıp becerindeki eksiği gösterebilir. İki dakika, başlamak için seçilmiş bir süre. Araştırmayla en iyi olduğu gösterilmiş süre değil. Özgüvenin aynı kalabilir. Yaptığın işi yine de kaydet."],example:{title:"Derya’nın fincan kulpu yine yamuk",text:"Derya montunu çıkardıktan sonra mutfak masasında bir fincan çiziyor. Kulp yine yamuk. Kendine daha fazla güvenmiyor. Notuna “Bir fincan çizdim. Kulpun oranlarını çalışmam gerekiyor” yazıyor. Sıradaki uygun öğleden sonra aynı küçük işi seçiyor. Bir fincan çizmiş olması, bir afiş tasarlayabildiğini göstermiyor. Notunda çizimin bittiği ve kulpun çalışılması gerektiği ayrı ayrı yazıyor."}},move:{invitation:"Kaydettiğin işi ve başlangıç anını koru. Ortaya çıkan işi ve kalan bir eksiği kaydet.",instructions:["Seçtiğin işi ve en küçük adımı aynı tut.","“Neye bakacaksın?” alanına çıkan işi ve kalan bir eksiği yaz."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Bir sonraki çayımı bitirince","Sonraki uygun molam başlayınca","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Fincanın kulpunu çizmek için birinden yardım iste","Kontrol etmem gereken bilgiyi cümlede işaretle","Açıklamasına ihtiyaç duyduğum yeri metinde işaretle"],observation:["Yaptığım çizim ve geliştirmem gereken bir ayrıntı","Yazdığım cümle ve kontrol etmediğim bir bilgi","Okuduğum paragraf ve anlamadığım bir nokta"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"Bir sonraki çayımı bitirince",place:"Evde, mutfak masamın başında",fallback:"Fincanın kulpunu çizmek için birinden yardım iste",observation:"Yaptığım çizim ve geliştirmem gereken bir ayrıntı",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"Sonraki uygun molam başlayınca",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Kontrol etmem gereken bilgiyi cümlede işaretle",observation:"Yazdığım cümle ve kontrol etmediğim bir bilgi",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Açıklamasına ihtiyaç duyduğum yeri metinde işaretle",observation:"Okuduğum paragraf ve anlamadığım bir nokta",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"Bir sonraki çayımı bitirince",placeHint:"Evde, mutfak masamın başında",obstacleHint:"Yaptığım işin bir kısmında yardıma ihtiyacım var",fallbackHint:"Fincanın kulpunu çizmek için birinden yardım iste",observationHint:"Yaptığım çizim ve geliştirmem gereken bir ayrıntı"},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Gücüne uygun, güvenli bir deneme seç. Kötü bir sonuç destek, değişiklik veya ara verme gerektirebilir."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Tam olarak ne yaptın, önüne hangi engel çıktı?"},judgment:{primary:{id:"turning-day-3-specific-record-decision",scenario:"Derya söz verdiği tek fincan çizimini bitirdi. Kulp yamuk, özgüveni de aynı. Şimdi kaydına ne yazacağını seçiyor.",question:"Bir sonraki denemeye hangi kayıt daha iyi yön verir?",options:[{id:"repeat-before-assessing",text:"Bitirdiği çizimi kaydetsin. Hangi ayrıntıyı çalışacağına karar vermeden önce aynı fincanı hiçbir şeyi değiştirmeden yeniden çizsin.",feedback:"Neyi çalışacağını bilmiyorsan tekrar yardımcı olabilir. Derya ise yamuk kulpu şimdiden görebiliyor. O ayrıntıyı şimdi kayda eklesin. Böylece sıradaki deneme belirli bir beceriyi sınayabilir."},{id:"specific-evidence",text:"Tamamladığı bir fincan çizimini ve yamuk kulpu kaydetsin. Sonra bir sonraki uygun deneme zamanını seçsin.",feedback:"Bu kayıt, Derya’nın ne yaptığını ve hangi ayrıntıyı hâlâ çalışması gerektiğini gösteriyor. Derya tek çizim hedefini karşıladı. Genel çizim becerisini kanıtlaması veya özgüveninin değişmesi gerekmiyor. Sıradaki denemede kulpa çalışabilir."},{id:"cue-reliability-from-once",text:"Çizimi bitirdiğini kaydetsin. Bugün işe yaradığı için bu başlangıç anını gelecek hafta da aynı şekilde kullansın.",feedback:"Umut veren bir başlangıç anını denemeye devam etmek makul. Ama tek tamamlanmış iş, düzenin güvenilir olduğunu göstermez. Kulptaki sorunu da kaydet. Sıradaki koşullarda aynı başlangıç anını yeniden sınayabilirsin."}],bestOptionId:"specific-evidence"}},carry:{takeaway:"Ne yaptığını tam anlat. Kalan beceri eksiği, sıradaki denemende ne çalışacağını göstersin.",followUp:{questionId:"turning-day-3-return",question:"Tamamladığın küçük iş neyi gösterdi, hangi kısmının üzerinde hâlâ çalışman gerekiyor?",observationPrompt:"Gerçekte ne yaptın ya da ne fark ettin?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"“Yapabilirim” dediğinde hangi işi kastediyorsun?",paragraphs:["Bandura’nın 1977 tarihli makalesi, öz yeterliği belirli bir davranışı yapmaya dair beklenti olarak anlatır [T09]. Kendi başardıkların, başkalarını gözlemek, cesaretlendirilmek ve bedensel durumlar bu beklentiye bilgi sağlar. Kuram, kişinin kendi deneyimine özellikle önem verir. Ama bu makale bir deney değildir. Her küçük işin özgüven yarattığını veya her ortamda kendi deneyiminin diğer desteklerden üstün olduğunu kanıtlamaz.","Bu ayrım, kurs boyunca kaydını işe yarar tutar. Tamamladığın çizim, o koşullarda o çizimi yaptığını gösterir. Araçların, başlangıç anın veya şu anki becerin hakkında bir şey öğretebilir. İnsan olarak değerini ölçmez. Gelecekteki her projeyi tamamlayabileceğini de göstermez. Bu tek denemeden, gösterdiğinden daha büyük bir sonuç çıkarma.","Yaptığın iş bir bilgi eksiğini gösteriyorsa sıradaki adım öğrenmek veya yardım almak olabilir. Gücün ya da güvenliğin değişirse adımı uyarla veya ara ver. Bu, gündelik gelişim için bir denemedir. Yoğun kaygının tedavisi veya kişiliğinin sınavı değildir."]},{heading:"Küçük bir başlangıç ile tamamlanmış iş aynı değil",paragraphs:["James Clear’ın iki dakika kuralı, uygulamaya dönük bir öneridir. İki dakikanın en iyi süre olduğunu gösteren kontrollü bir araştırma bulgusu değildir [T17]. Kısa bir başlangıç, işe el atmayı kolaylaştırabilir. Ama kalemi ortaya koymak hazırlık, bir nesne çizmek çizim denemesidir. İstediğin yola gerçekten katkısı olan en küçük adımı seç. Uygun adım hazırlıksa bunu dürüstçe hazırlık olarak kaydet.","Harkin ve arkadaşlarının 138 rastgele kontrollü araştırmayı birleştiren derlemesinde, ilerlemeyi izlemek hedefe ulaşmayı ortalama olarak artırdı [T05]. Hedefler ve yöntemler farklıydı. Ek analizlerde ilerlemeyi fiziksel olarak kaydetmek daha büyük etkilerle ilişkiliydi. Bu sonuç, ODA’nın tam bu not biçimini doğrulamaz. Başkalarıyla açıkça paylaşmayı da gerektirmez.","Kısa bir not hem yaptığın işi hem eksik kalan noktayı gösterebilir: işe yarayan bir cümle yazdım, ama bir bilgi hâlâ kontrol edilmeli. Adım iyi hissettirdi diye sonucu büyütme. Hayal kırıklığı yarattı diye de yaptığını silme. Sıradaki küçük işi elindeki kayda göre seç."]}],sourceIds:["T09","T05","T17"]}},{schemaVersion:2,revision:2,id:"turning-day-4",courseId:"turning-day",locale:"tr",title:"Sonraki adımını aramakla vakit kaybetme",goal:"Sürdürdüğün küçük adımı, seçtiğin başlangıç anında tek bir ortam değişikliğiyle dene.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Gereken malzeme ortada yokken dikkatini dağıtan şey hemen elinin altında mıydı?",reason:{id:"turning-day-4-reason",label:"Gereken şeyler ulaşılır kalsın. Hazırlığın hangi kısmını kolaylaştırabilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Başlama anında araçlarım hazır olsun","Gerekli arama ve mesajlara ulaşayım","Kendime sakladığım bir kayıt tutayım"]},why:{id:"turning-day-4-why",label:"Gereken şeyler ulaşılır kalsın. Hazırlığın hangi kısmını kolaylaştırabilirsin?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Başlangıç anı sadece telefondan gelen hatırlatma değildir. İşin yapılacağı ortam da buna dahildir. Araştırmalar, benzer ortamlarda tekrarlanan bir davranışın zamanla o ortamdaki işaretlerle daha çok başlayabildiğini anlatır. Gerekli malzemeyi hazır tutmak hazırlık yükünü azaltabilir. Ama çabayı ortadan kaldırmaz, hatırlayacağını da garanti etmez. Hazır olması, işi senin yerine yapması demek değil.","Son denemenin kaydına bak. Engel malzemeyi bulmaksa onu başlangıç anında kullanacağın yere koy. Sonra küçük işini orada dene. Gerekli aramalar, bakım sorumluluklarıyla ilgili bildirimler ve erişim araçları ulaşılabilir kalsın. Kaydını kendine saklayabilirsin. Bir nesnenin yerini değiştirmek hazırlıktır. Küçük işi yapmak ise bu hazırlığı sınar."],example:{title:"Derya telefonu ulaşılabilir tutuyor",text:"Derya son çizim fırsatını kâğıt ararken kaçırdı. Bu kez not kâğıdını ve kalemi çay fincanının yanına koyuyor. Çaydan sonra kaşığı çiziyor. Ailesi arayabilsin diye telefonu ulaşılabilir kalıyor. Çizimini sadece kendisinin gördüğü bir kayda ekliyor. Bu hazırlık bugün işe yaradı. Yarınki vardiya için başka bir başlangıç anı gerekebilir. Tek deneme henüz düzeni kanıtlamıyor."}},move:{invitation:"Kaydettiğin işi, başlangıç anını ve yeri koru. Hazırlıkta tek bir değişikliği dene.",instructions:["“Neye bakacaksın?” alanına bir malzeme veya erişim değişikliği yaz.","Aynı en küçük adımı bu yeni hazırlıkla dene."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Bir sonraki çayımı bitirince","Önceden ayırdığım mola başladığında","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Rahatça kullanabildiğim yedek kalemle çizimi dene","Bana uygun olan yedek yazma aracımı kullan","Metnin bana uygun, erişilebilir bir kopyasını aç"],observation:["Kalemin hangi yerde durması çizime yardımcı oldu?","Dosyaya erişimde hangi değişiklik yazmayı kolaylaştırdı?","Metne erişimde hangi değişiklik okumayı kolaylaştırdı?"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"Bir sonraki çayımı bitirince",place:"Evde, mutfak masamın başında",fallback:"Rahatça kullanabildiğim yedek kalemle çizimi dene",observation:"Kalemin hangi yerde durması çizime yardımcı oldu?",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"Önceden ayırdığım mola başladığında",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Bana uygun olan yedek yazma aracımı kullan",observation:"Dosyaya erişimde hangi değişiklik yazmayı kolaylaştırdı?",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Metnin bana uygun, erişilebilir bir kopyasını aç",observation:"Metne erişimde hangi değişiklik okumayı kolaylaştırdı?",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"Bir sonraki çayımı bitirince",placeHint:"Evde, mutfak masamın başında",obstacleHint:"Gereken malzemeleri bulmak ya da onlara ulaşmak zor",fallbackHint:"Rahatça kullanabildiğim yedek kalemle çizimi dene",observationHint:"Kalemin hangi yerde durması çizime yardımcı oldu?"},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Hazırlığını değiştirirken acil iletişim, bakım sorumlulukları ve erişim için gereken arama ve mesajları ulaşılabilir tut."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Hangi hazırlık değişikliğini denedin, ardından gerçekte hangi işi yaptın?"},judgment:{primary:{id:"turning-day-4-decision",scenario:"Derya kâğıt ararken bir çizim fırsatını kaçırdı. Ailesi arayabilsin diye telefonu ulaşılabilir olmalı. İlerlemesini de kendine saklamak istiyor.",question:"Bu durumda hangi adım ona daha uygun?",options:[{id:"mute-nonessential-alerts",text:"Gereksiz bildirimleri kapatıp aile aramalarını açık tutsun. Kâğıdın nerede olduğunu hatırlamaya güvenerek aynı şekilde devam etsin.",feedback:"Bu seçim gerekli iletişimi korur ve kesintileri azaltabilir. Ama kayıtta görünen malzeme bulma sorununu değiştirmez. Çizim malzemelerini çay molasında kullanacağın yere koy. Sonra aynı küçük çizimi dene."},{id:"ready-tools",text:"Kâğıdı çay fincanının yanına koysun. Aile aramaları açık kalsın. Bir çizim yapıp kaydını kendine saklasın.",feedback:"Bu adım, kaydını paylaşmanı veya iletişimi kesmeni gerektirmeden malzeme bulma sorununa odaklanıyor. Bir çizim denemesi, hazır malzemenin bu belirli fırsatta yardımcı olup olmadığını gösterir."},{id:"private-reminder-first",text:"Çaydan sonrası için sadece kendisinin gördüğü bir çizim hatırlatması kursun. Kâğıdı her zamanki yerinde bıraksın.",feedback:"Hatırlatma, başlangıç anını fark etmeyi kolaylaştırabilir. Derya zaten çay molasını fark ediyor. Sorun kâğıdı bulamaması. Önce malzemenin yerini sınasın. Sonra fark etmek sorun olursa hatırlatmayı düşünsün."}],bestOptionId:"ready-tools"}},carry:{takeaway:"Hazırlığını işi yaparken dene. Kaydının gizliliğini ve gerekli araçlara, iletişim kanallarına erişimini koru.",followUp:{questionId:"turning-day-4-return",question:"Hazırlıktaki değişiklik, başlangıç anını kullanıp küçük işini yapmana yardımcı oldu mu?",observationPrompt:"Hangi hazırlık değişikliği kaydettiğin işi kolaylaştırdı, hangisi hiç yardımcı olmadı?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"Ortam yardımcı olabilir, işi senin yerine yapmaz",paragraphs:["Wood ve Rünger’in derlemesi, benzer ortamlarda tekrarlanan davranışların zamanla ortamdaki işaretlerle başlayabildiğini anlatır [T08]. Bilinçli hedefler ile alışkanlıklar birlikte işleyebilir. Bu, farklı araştırmaları birleştiren bir derlemedir. Bir nesneyi belirli yere koymanın herkeste işe yaradığını kanıtlayan bir deney değildir. İradenin sınırlı bir pil olduğunu veya hazırlığın planlama ve başlama güçlüklerini ortadan kaldırdığını göstermez.","Lally ve arkadaşları, gündelik sağlık davranışlarını 84 gün boyunca izledi [T06]. Aynı ortamda tekrarlarla birlikte, kişilerin bildirdiği otomatiklik arttı. Rastgele atanmış, deneme yapmayan bir kontrol grubu yoktu. Bu araştırmadan garantili bir süre çıkaramayız. Bir fincanın yanına kalem koymanın tam etkisini de bu çalışma kanıtlamaz.","ODA küçük bir ortam değişikliğini denemeni istiyor. Çünkü son kaydın belirli bir hazırlık yükü gösterdi. İşini, başlama anını ve en küçük adımını aynı tut. Böylece sıradaki gözlemin somut bir soruyu yanıtlar: gerekli malzemeler elinin altında mıydı, onları gerçekten kullandın mı?"]},{heading:"Kaydını kendine saklayarak da ilerleyebilirsin",paragraphs:["Harkin ve arkadaşları, ilerlemeyi izlemeye dair 138 rastgele kontrollü araştırmayı inceledi [T05]. İzlemeyi artıran uygulamalar hedefe ulaşmayı ortalama olarak artırdı. Ek analizlerde fiziksel kayıt ve bildirim daha büyük etkilerle ilişkiliydi. Ama bu karşılaştırmalar tek bir arkadaşın yeterli olduğunu, herkese açık paylaşım gerektiğini veya kaydını kendine saklamanın daha kötü bir yol olduğunu kanıtlamaz.","İstersen destekleyici biriyle konuşmayı seçebilirsin. Kişiyi, paylaşacağın bilgiyi ve zamanı sen belirlersin. Burada yalnızca senin gördüğün, somut bir not da tam bir seçenektir. Hedefini başkalarına anlatman, alkış istemen veya yanında güvende olmadığın birinden baskı görmen gerekmiyor.","Telefonun yerini değiştirirken de gereken iletişimi ve erişimi koru. Gördüğün engeli hedefle: ulaşamadığın malzeme, bulamadığın belge veya gereksiz bildirim. Hazırlığı hazırlık olarak kaydet. Ardından aynı küçük işi denediğinde ne olduğuna bak. Sadece ortamı değiştirmiş olman, işi yaptığını göstermez."]}],sourceIds:["T08","T05","T06"]}},{schemaVersion:2,revision:2,id:"turning-day-5",courseId:"turning-day",locale:"tr",title:"“Bugün yapamadım.” Önce kayıtta ne olduğuna bak",goal:"Gerçek denemene dönüp bak. Geçmişi değiştirmeden bir sonraki uygun fırsatı kaydet.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bugüne “başarısızlık” mı diyorsun? Kaydında gerçekte ne var?",reason:{id:"turning-day-5-reason",label:"Kaydına bakınca hangi şeyin değişmesi gerektiğini görüyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Hazırlık ile gerçek denemeyi birbirinden ayrı tutmak","Kaçırdığım fırsatta ne olduğunu anlayıp öğrenmek","Yarın yapacağımı bugün yapılmış saymamak"]},why:{id:"turning-day-5-why",label:"Kaydına bakınca hangi şeyin değişmesi gerektiğini görüyorsun?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bugün yaptığını kayda, yarın yapmak istediğini plana koy. Araştırmalar ilerlemeyi kontrol etmeyi ortalama olarak destekliyor. Aracın hazır olması, denemeyi yaptığını göstermez. Seçtiğin en küçük adımı koru. Yeni planın geçmişte yaptığını değiştirmez. Hazırlığı ve asıl işi ayrı tut.","En son denemende ne yaptığını veya hangi adımın eksik kaldığını söyle. Sonra bir sonraki uygun fırsatı seç. Bir çalışmada kendini affetmek, sonraki sınav için daha az ertelemeyle ilişkiliydi. Bu ilişki, affetmenin ertelemeyi azalttığını veya kendine anlayışlı bir cümle söylemenin işe yaradığını göstermez. Kendine yüklenmeden, başarı uydurmadan bak. Geç saatte değerlendirmek kaygını artırıyorsa daha erken bir zaman seç."],example:{title:"Derya kâğıdı hazırladı ama çizmedi",text:"Derya kâğıdı fincanının yanına koydu. Ama işten geç çıktı. Akşam çayını içti ve çizmedi. Günü kapatmadan önce hazırlığı ayrı kaydediyor. Çizim için “Henüz değil” seçeneğini işaretliyor. Yarın çaydan sonra yapacağı çizim ise plan olarak kalıyor. Kısa bir değerlendirme yapıyor. Hâlâ hayal kırıklığı hissediyor. Bu his, hazırlığı yapılmış çizim saymasını gerektirmiyor."}},move:{invitation:"Kaydettiğin denemeye bak. İşi koru, kaydın gösterdiği tek bir koşulu değiştir.",instructions:["Bir sonraki denemeyi değiştirmeden önce gerçekten ne olduğunu kaydet.","İşi ve en küçük adımı koru. Sadece uymayan koşulu değiştir."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Bir sonraki erken çay molamda","Bir sonraki erken iş molamda","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Dinlen; yarın daha erken çay molasında dene","Dinlen; yarın daha erken iş molasında dene","Dinlen; yarın daha erken yemeğin ardından oku"],observation:["Yeni seçtiğim anda ortaya çıkan çizim","Yeni seçtiğim anda yazdığım işe yarayan cümle","Yeni seçtiğim anda okuyup bitirdiğim paragraf"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"Bir sonraki erken çay molamda",place:"Evde, mutfak masamın başında",fallback:"Dinlen; yarın daha erken çay molasında dene",observation:"Yeni seçtiğim anda ortaya çıkan çizim",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"Bir sonraki erken iş molamda",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Dinlen; yarın daha erken iş molasında dene",observation:"Yeni seçtiğim anda yazdığım işe yarayan cümle",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Dinlen; yarın daha erken yemeğin ardından oku",observation:"Yeni seçtiğim anda okuyup bitirdiğim paragraf",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"Bir sonraki erken çay molamda",placeHint:"Evde, mutfak masamın başında",obstacleHint:"İş geç bitince başka bir şeye gücüm kalmıyor",fallbackHint:"Dinlen; yarın daha erken çay molasında dene",observationHint:"Yeni seçtiğim anda ortaya çıkan çizim"},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Değerlendirmek kaygını artırıyor veya uykunu açıyorsa dur. Daha erken bir değerlendirme zamanı ya da dinlenmeyi seç."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Tam olarak ne yaptın, önüne hangi engel çıktı?"},judgment:{primary:{id:"turning-day-5-decision",scenario:"Derya işten geç çıktığı gün söz verdiği tek çizimi yapmadı. Kâğıdı hazırlamıştı. Yarın daha erken çay molası verebilir. Hafta sonu daha uzun zaman ayırması da mümkün.",question:"Bu durumda hangi adım ona daha uygun?",options:[{id:"same-cue-new-alert",text:"Çizim için “Henüz değil” kaydı girsin. Akşamki başlama anını koruyup aynı saate bir hatırlatma eklesin.",feedback:"Bu seçim kaydı dürüst tutuyor. Hatırlatma fark etmeyi ele alır. Derya’nın sorunu ise geç işten sonra gücünün kalmamasıydı. Daha erken çay molasında aynı küçük adımı daha uygun koşullarda deneyebilir."},{id:"honest-change",text:"Hazırlığı ayrı kaydetsin. Çizim için “Henüz değil” seçeneğini seçsin. Aynı küçük iş için daha erken ve uygun bir an seçsin.",feedback:"Bu seçim söz verilen küçük adımı korur, ne olduğunu anlatır. Yarın yapacağı iş hâlâ plandır. Derya hazırlığı çizim saymadan ve bütün günü kötü ilan etmeden başlangıç anını değiştirebilir."},{id:"weekend-session",text:"Çizim için “Henüz değil” kaydı girsin. Denemesini hafta sonunda ayırabileceği daha uzun bir zamana taşısın.",feedback:"Hafta sonu daha iyi uyuyorsa onu seçebilir. Ama burada yarın erken bir mola var. Aynı küçük işi orada denemek, zamanı ve işin büyüklüğünü birlikte değiştirmeden önce daha küçük bir değişikliği sınar."}],bestOptionId:"honest-change"}},carry:{takeaway:"Geçmişi olduğu gibi dürüstçe kaydet. Elindeki gerçekler gerektiriyorsa bir sonraki deneme fırsatını değiştir.",followUp:{questionId:"turning-day-5-return",question:"Yeni seçtiğin fırsat hayatına daha iyi uydu mu, orada gerçekten ne yaptın?",observationPrompt:"Gerçekte ne yaptın ya da ne fark ettin?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"Dürüst değerlendirme sorumluluğu korur",paragraphs:["Wohl ve arkadaşları, iki ara sınavın çevresinde 119 birinci sınıf öğrencisini izledi [T12]. İlk erteleme için kendini daha fazla affetmek, sonraki sınav öncesinde daha az ertelemeyle ilişkiliydi. Bu, tek bir derste yapılmış gözlemsel araştırmaydı. Affetmenin değişime neden olduğunu, hazır bir cümlenin davranışı değiştirdiğini veya kendine yüklenmenin her zaman kaçınma yarattığını göstermez.","Doğru kayıt tutmak için önce kendini affetmiş hissetmen gerekmez. “Kâğıdı hazırladım ama iş geç bittiği için çizmedim” iki ayrı olguyu anlatır. “Yarın ilk çayımdan sonra çizeceğim” ise bir plandır. İlk deneme hayal kırıklığı yaratsa da bu ayrımları koru. Hazırlık yapılmış olabilir, asıl iş henüz yapılmamış olabilir.","İlerlemeyi izlemek için daha geniş deneysel destek var [T05]. Yine de o derleme ODA’nın bu belirli kayıt ve dönüş akışını değerlendirmedi. Buradaki amaç pratik: elindeki bilgiyle sıradaki koşulu seçmek. Planını kanıt gibi sunmadan, yaptığın iş ile yapmayı istediğin işi ayrı kaydetmek."]},{heading:"Yatmadan önce liste yazma bulgusunun sınırı var",paragraphs:["Scullin ve arkadaşları bir laboratuvar gecesinde, 18–30 yaşındaki 57 sağlıklı yetişkinin verisini inceledi [T11]. Katılanlar kâğıt ve kalemle beş dakika boyunca ya ilerideki işleri ya da tamamlanan işleri yazdı. Gelecek işleri yazan grup ortalama olarak daha çabuk uyudu: 15,82 dakikaya karşı 25,09 dakika. Karşılaştırma, hiç yazmamakla değil başka bir yazma işiyleydi. Toplam uykuda istatistiksel olarak anlamlı artış gösterilmedi.","Bu sonuç; sözlü telkinleri, yarını hayal etmeyi veya başarıları gözden geçirmeyi uyku tedavisi olarak doğrulamaz. Beş dakikalık kâğıt işi ayrı bir uygulamaydı. ODA’nın kısa değerlendirmesi ve planı, o sınanmış uygulama değildir. Uyku sözü vermez, yatmadan önce yazmanı da gerektirmez.","Değerlendirmek kaygını artırıyor veya seni uyanık tutuyorsa dur. Daha erken bir zaman seç. Dinlenmek uygun adım olabilir. Süren uyku güçlükleri için kursun bitmesini beklemeden bir uzmana danışabilirsin. Aynı küçük iş denemeni sürdür. Bunun için yeni bir gece ritüeli eklemene gerek yok."]}],sourceIds:["T05","T12","T11"]}},{schemaVersion:2,revision:2,id:"turning-day-6",courseId:"turning-day",locale:"tr",title:"Birkaç gün yapamadın mı? Haftanı hayatına göre planla.",goal:"Kayıtlarına bakarak aynı deneme için gerçekçi bir hafta planla. Güvenli molalara da yer bırak.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Kayıtların, hayalindeki değil gerçekten yaşadığın hafta hakkında ne söylüyor?",reason:{id:"turning-day-6-reason",label:"Bu küçük iş, ayırabildiğin zaman ve güçle istediğin yola katkı sağlıyor mu?",kind:"text",maxLength:160,optional:!0,suggestions:["Hayatıma uyan kısmı aynı şekilde korumak","Telafi işi eklemek yerine başlama anını değiştirmek","Dinlenip toparlanmak için de yer ayırmak"]},why:{id:"turning-day-6-why",label:"Bu küçük iş, ayırabildiğin zaman ve güçle istediğin yola katkı sağlıyor mu?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Aynı denemenin planladığın fırsatlarını, gerçekten yaptığın denemeleri ve çıkan işi karşılaştır. Bir hafta hayatına uyumu sınar. Alışkanlık oluştuğunu göstermez. Sık duyduğun 18–254 gün, insanları yalnızca 84 gün izleyen bir çalışmadaki model tahminlerinden geldi. Bunlar gözlenmiş bitiş günleri veya herkes için geçerli süreler değildi. Kendi haftanı o sayılarla yargılama.","Küçük işi koru veya küçült. Başlangıç anını değiştir ya da ara ver. İncelenen çalışmada tek kaçırılan fırsat süreci belirgin biçimde bozmadı. İki kez aksama sınırı belirlenmedi. Bir sonraki uygun fırsatı kaydet. ODA ertesi gün ne olduğuna bakman için zaman ayırır. Geçmiş kayıtlarını boşluklarıyla birlikte koru."],example:{title:"Derya’nın haftası eksiksiz değil",text:"Derya beş çizim fırsatı planladı, üçünde çizdi. İki boşluk da geç vardiyaların ardından geldi. Pazar çayında tek nesne hedefini koruyor. Yalnızca geç vardiya günlerindeki başlangıcı pazartesi öğleden sonraki molaya taşıyor. Bu fırsatı kaydedince ODA salı günü denemesine bakması için zaman ayırıyor. Kabaca yaptığı üç çizim yine üç çizim. Yapmadığı iki deneme kayıtta kalıyor."}},move:{invitation:"Kaydettiğin küçük işi ve sana uyan başlama anını koru. Sadece seni durduran koşulu değiştir.",instructions:["Henüz kaydın yoksa ilk uygun deneme fırsatını seç.","Sonraki fırsatı kaydet. ODA ertesi gün ne olduğunu gözden geçirmen için zaman ayırır."],prompts:[],suggestions:{action:["Gündelik bir nesneyi çiz","İşe yarayan bir cümle yaz","Gereken metinden bir paragraf oku"],minimum:["Küçük bir çizimi tamamla","İşe yarayan tek bir cümle yaz","Bir paragrafı baştan sona oku"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],cue:["Sonraki öğleden sonra çay molam başlayınca","İşte sonraki uygun molam başlayınca","Sonraki öğünümü bitirince"],place:["Evde, mutfak masamın başında","Genellikle çalıştığım masa veya tezgâhta","Rahatça erişebildiğim okuma yerinde"],minutes:[2,1,5],fallback:["Dinlen; bir sonraki öğleden sonra molasında dene","Yarın işte önceden ayırdığım mola zamanında dene","Bir sonraki uygun yemekten sonra paragrafı oku"],observation:["Yaptığım çizim; zaman uygun muydu?","Yazdığım cümle; zaman uygun muydu?","Bitirdiğim paragraf; zaman uygun muydu?"],bundles:[{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",cue:"Sonraki öğleden sonra çay molam başlayınca",place:"Evde, mutfak masamın başında",fallback:"Dinlen; bir sonraki öğleden sonra molasında dene",observation:"Yaptığım çizim; zaman uygun muydu?",minutes:2},{action:"İşe yarayan bir cümle yaz",minimum:"İşe yarayan tek bir cümle yaz",cue:"İşte sonraki uygun molam başlayınca",place:"Genellikle çalıştığım masa veya tezgâhta",fallback:"Yarın işte önceden ayırdığım mola zamanında dene",observation:"Yazdığım cümle; zaman uygun muydu?",minutes:2},{action:"Gereken metinden bir paragraf oku",minimum:"Bir paragrafı baştan sona oku",cue:"Sonraki öğünümü bitirince",place:"Rahatça erişebildiğim okuma yerinde",fallback:"Bir sonraki uygun yemekten sonra paragrafı oku",observation:"Bitirdiğim paragraf; zaman uygun muydu?",minutes:2}]},suggested:{action:"Gündelik bir nesneyi çiz",minimum:"Küçük bir çizimi tamamla",minutes:2,cueHint:"Sonraki öğleden sonra çay molam başlayınca",placeHint:"Evde, mutfak masamın başında",obstacleHint:"Geç biten vardiyalar bu deneme zamanına izin vermiyor",fallbackHint:"Dinlen; bir sonraki öğleden sonra molasında dene",observationHint:"Yaptığım çizim; zaman uygun muydu?"},accessibleAlternative:"Seçtiğin küçük adım için yazarak ya da sesle yazdırarak ilerle. Sana uygun araçları kullan veya yardım iste.",stopRule:"Hastalık, bitkinlik, bakım sorumlulukları veya güvensiz koşullar bir süre ara vermeni gerektirebilir. Yeniden başlamak mümkün olduğunda dön."},result:{question:"Seçtiğin en küçük adımı denediğinde tam olarak ne oldu?",observationPrompt:"Tam olarak ne yaptın, önüne hangi engel çıktı?"},judgment:{primary:{id:"turning-day-6-observed-fit-decision",scenario:"Derya beş çizim planladı, üçünü yaptı. İki boşluk geç vardiyaların ardından geldi. Tek nesne hedefi diğer deneme zamanlarında ona uydu.",question:"Bu durumda hangi adım ona daha uygun?",options:[{id:"shrink-before-moving",text:"Geç vardiya sonrasındaki başlangıcı korusun. Her çizimi tek dış hatta indirsin. Sonraki haftayı yine dürüstçe karşılaştırsın.",feedback:"Engel işin büyüklüğüyse küçültmek yardımcı olabilir. Ama mevcut hedef başka fırsatlarda uydu. Önce işe yarayan kapsamı değiştirmek yerine daha uygun bir başlangıç anını dene. Kayıt şu anda bunu gösteriyor."},{id:"adjust-week",text:"Tek nesne hedefini korusun. Geç vardiya sonrasındaki başlangıç anını değiştirsin. Beş fırsatın bütün kayıtları olduğu gibi kalsın.",feedback:"Bu seçim, denemelerinde gördüğü soruna göre planı değiştiriyor ve geçmişi dürüst tutuyor. Derya başka bir uygun başlangıç anını sınayabilir. Üç çizim ortaya çıkan iştir. Tamamlanmış bir alışkanlığın kanıtı değildir."},{id:"compensate-output",text:"Geç vardiya sonrasındaki başlangıcı korusun. Yapamadığı çizimleri telafi etmek için boş günlerinde daha fazla nesne çizsin.",feedback:"Fazladan çizmek, kendisi seçerse amacına katkı sağlayabilir. Ama bilinen başlangıç çatışmasını değiştirmez. Telafi yükü eklemeden önce geç vardiya günlerindeki fırsatı düzelt. Sonra daha fazla iş isteyip istemediğine bak."}],bestOptionId:"adjust-week"}},carry:{takeaway:"Kayıtlarına bakarak gelecek haftayı planla. Dinlenmeye ve güvenli molalara da yer ver.",followUp:{questionId:"turning-day-6-return",question:"Seçtiğin değişiklik, sıradaki fırsatta küçük işini yapmanı gerçekten mümkün kıldı mı?",observationPrompt:"Gerçekte ne yaptın ya da ne fark ettin?",adjustmentPrompt:"Bir sonraki fırsatta ne aynı kalsın, neyi değiştirmek istersin?"}},goDeeper:{sections:[{heading:"O alışkanlık süresi bir model tahminiydi",paragraphs:["Lally ve arkadaşları, 96 gönüllüyü 84 gün izledi [T06]. 82 kişi yeterli veri verdi. 62 kişinin verisi için eğriler hesaplandı. Bunların 39’u verilere iyi uydu. Bu 39 eğride, kişinin otomatiklik düzeyinin üst sınırının %95’ine ulaşması için tahmin edilen süre 18 ile 254 gün arasındaydı. Ortanca 66 gündü. 254 gün, gözlem süresinin ötesine uzanan bir model tahminiydi. Araştırmada görülmüş bir bitiş değildi.","Çalışma, gündelik sağlık davranışları için kişilerin kendi bildirimlerine dayanıyordu. Rastgele atanmış kontrol grubu yoktu. Tek bir fırsatın kaçırılması, incelenen süreci belirgin biçimde bozmadı. Bu bulgu, iki kez aksamanın alışkanlığı yok ettiği bir eşik belirlemez. Üst üste ara vermek, karakterinin zayıf olduğunu da göstermez.","Bu kursta planladığın hafta, planın hayatına uyup uymadığını sınar. Çizim, öğrenme, bakım veya toparlanma adımın çalışılan davranışlardan farklı olabilir. Uyumu gerçek fırsatlar ve çıkan işle değerlendir. Gün serisini, araştırmayla doğrulanmış bir dönüşüm ölçüsü gibi kullanma."]},{heading:"Elindeki denemeyi toparla, yenisini eklemek gerekmez",paragraphs:["2024 tarihli bir derleme, toplam 2.601 kişinin katıldığı 20 sağlık davranışı alışkanlık çalışmasını kapsadı [T07]. Yalnızca dört çalışma oluşma süresi tahmini verdi. On birinde yanlılık riski yüksekti. Tanımlar ve yöntemler farklıydı. Tek bir takvim çıkarmak mümkün değil. Alışkanlık gücünün öncesi ve sonrası arasındaki fark, kontrollü tedavi etkisini veya senin davranışının ne zaman otomatikleşeceğini göstermez.","İlerlemeyi izlemeyi artıran uygulamalar, 138 rastgele kontrollü çalışmada hedefe ulaşmayı ortalama olarak artırdı [T05]. Burada yeni ritüel eklemek yerine mevcut kayıtlarını kullan. Planladığın fırsatları, bildirdiğin denemeleri ve ortaya çıkan işleri ayrı say. Ne olduğunu söyleyene kadar eksik bir kayıt bilinmeyen olarak kalır.","Bu denemeyi hâlâ seçtiğin yol için yapmak istiyor musun? Sana uyan küçük işi tekrarla. Sorun çıkaran koşulu değiştir, destek al, dinlen veya dur. Bir sonraki denemeyi kaydedince ODA ertesi gün ne olduğunu gözden geçirmen için zaman ayırır. İstersen kendi takviminde haftalık karşılaştırma için de zaman seçebilirsin. Burada ikinci bir randevu oluşturulmaz. Dersi bitirmek ile planını uygulamak ayrı şeylerdir."]}],sourceIds:["T06","T07","T05"]}}],m=[{id:"1676475382103-54041209cf6c",alt:"Kahve fincanının yanında deftere not yazan kadın"},{id:"1740815897057-a93a8cf98a70",alt:"Parkta ağaçların arasındaki yolda yürüyen kadın"},{id:"1758854486305-eb7621f1e2e4",alt:"Büyük kemerli pencerenin yanında masada çalışan kişi"},{id:"1756312177615-e153c9db507d",alt:"Mutfakta telefonda konuşan kadın"},{id:"1768219565623-501f93ae384b",alt:"Akşam bir lambayla aydınlanan masa"},{id:"1529651737248-dad5e287768e",alt:"Planlama takviminin üzerinde duran kalem"}],t=[0,1,1,1,1,1],k=[3,3,3,3,3,3],s={id:"turning-day",title:"Pazartesiyi bekleme. Bugün küçük bir başlangıç yap",subtitle:"Altı ders. İşe yarayan tek değişikliği dene, engeli gör ve haftanı hayatına göre planla.",description:"Hayatında önem verdiğin bir konuda işe yarayan tek bir adım at. Aynı denemeyi altı ders boyunca sürdür. Engeli gör, hazırlığı işin içinde dene, yaptığını dürüstçe kaydet. Gelecek haftayı bu kayda göre planla.",scope:"Yetişkinler için kişisel gelişim eğitimi. Terapi, tanı veya tedavi değildir. Tek günde hayatının değişeceğine söz vermez. Doktorunla konuşmadan tedavini veya ilacını bırakma. Yoğun kaygı, çökkünlük veya günlük hayatını zorlaştıran sıkıntı yaşıyorsan bir sağlık uzmanına başvur. Kendine zarar verme düşüncen veya acil tehlike varsa bulunduğun yerdeki acil yardım numarasını ara.",outcome:"Denenmiş veya ara verilmiş bir değişiklik, gerçeklere dayalı kayıt ve sıradaki uygun tarih.",photo:{id:"1570821805833-1103c43f9c1d",alt:"Ağaçlar arasındaki patikaya düşen güneş ışınları"},lang:"tr",lessons:d.map((a,n)=>{const e=a.judgment.primary,r=e.options.find(i=>i.id===e.bestOptionId),l=e.options.filter(i=>i.id!==e.bestOptionId);return l.splice(t[n],0,r),{id:a.id,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,practice:[...a.move.instructions,"Buraya dönüp gerçekte ne olduğunu kaydet."].slice(0,k[n]),reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:l.map(i=>i.text),correct:t[n],feedback:r.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds,deeper:a.goDeeper.sections,example:a.idea.example,photo:m[n]}})};export{s as COURSE,d as LESSONS_V2,y as SOURCES};
